-- Public-domain quotes on writing, discipline, self-improvement and decisions.
-- Translations are public-domain ones (George Long, Richard Gummere, James Legge, W. D. Ross).
-- Well-known misattributions are deliberately left out.
INSERT INTO quotes (text, author, source) VALUES
-- Marcus Aurelius
($q$Such as are your habitual thoughts, such also will be the character of your mind; for the soul is dyed by the thoughts.$q$, 'Marcus Aurelius', 'Meditations, V.16'),
($q$Waste no more time arguing about what a good man should be. Be one.$q$, 'Marcus Aurelius', 'Meditations, X.16'),
($q$If it is not right, do not do it; if it is not true, do not say it.$q$, 'Marcus Aurelius', 'Meditations, XII.17'),
($q$That which is an obstacle on the road helps us on this road.$q$, 'Marcus Aurelius', 'Meditations, V.20'),
($q$Very little is needed to make a happy life; it is all within yourself, in your way of thinking.$q$, 'Marcus Aurelius', 'Meditations, VII.67'),
($q$Do every act of your life as if it were the last.$q$, 'Marcus Aurelius', 'Meditations, II.5'),
($q$Look within. Within is the fountain of good, and it will ever bubble up, if you will ever dig.$q$, 'Marcus Aurelius', 'Meditations, VII.59'),
($q$Confine yourself to the present.$q$, 'Marcus Aurelius', 'Meditations, VII.29'),
($q$How much more grievous are the consequences of anger than the causes of it.$q$, 'Marcus Aurelius', 'Meditations, XI.18'),
($q$Loss is nothing else but change, and change is Nature's delight.$q$, 'Marcus Aurelius', 'Meditations, IX.35'),
($q$The best way of avenging yourself is not to become like the wrong-doer.$q$, 'Marcus Aurelius', 'Meditations, VI.6'),
($q$Time is a sort of river of passing events, and strong is its current.$q$, 'Marcus Aurelius', 'Meditations, IV.43'),
($q$Nowhere either with more quiet or more freedom from trouble does a man retire than into his own soul.$q$, 'Marcus Aurelius', 'Meditations, IV.3'),
($q$Think not so much of what you lack as of what you have.$q$, 'Marcus Aurelius', 'Meditations, VII.27'),
($q$Never esteem anything as of advantage to you that will make you break your word or lose your self-respect.$q$, 'Marcus Aurelius', 'Meditations, III.7'),
($q$Remember that man lives only in the present, in this fleeting instant; all the rest of his life is either past and gone, or not yet revealed.$q$, 'Marcus Aurelius', 'Meditations, III.10'),
($q$In the morning when you rise unwillingly, let this thought be present: I am rising to the work of a human being.$q$, 'Marcus Aurelius', 'Meditations, V.1'),
($q$Accept the things to which fate binds you, and love the people with whom fate brings you together, but do so with all your heart.$q$, 'Marcus Aurelius', 'Meditations, VI.39'),
-- Seneca
($q$It is not that we have a short time to live, but that we waste a lot of it.$q$, 'Seneca', 'On the Shortness of Life, I'),
($q$Life is long if you know how to use it.$q$, 'Seneca', 'On the Shortness of Life, II'),
($q$While we are postponing, life speeds by.$q$, 'Seneca', 'Letters to Lucilius, I'),
($q$Nothing, Lucilius, is ours, except time.$q$, 'Seneca', 'Letters to Lucilius, I'),
($q$Hold every hour in your grasp. Lay hold of to-day's task, and you will not need to depend so much upon to-morrow's.$q$, 'Seneca', 'Letters to Lucilius, I'),
($q$The primary indication of a well-ordered mind is a man's ability to remain in one place and linger in his own company.$q$, 'Seneca', 'Letters to Lucilius, II'),
($q$Everywhere means nowhere.$q$, 'Seneca', 'Letters to Lucilius, II'),
($q$Each day acquire something which will fortify you against poverty, against death, indeed against other misfortunes as well.$q$, 'Seneca', 'Letters to Lucilius, II'),
($q$Associate with those who will make a better man of you.$q$, 'Seneca', 'Letters to Lucilius, VII'),
($q$We suffer more often in imagination than in reality.$q$, 'Seneca', 'Letters to Lucilius, XIII'),
($q$If a man does not know to which port he is sailing, no wind is favourable.$q$, 'Seneca', 'Letters to Lucilius, LXXI'),
($q$As long as you live, keep learning how to live.$q$, 'Seneca', 'Letters to Lucilius, LXXVI'),
($q$No man was ever wise by chance.$q$, 'Seneca', 'Letters to Lucilius, LXXVI'),
($q$It is a rough road that leads to the heights of greatness.$q$, 'Seneca', 'Letters to Lucilius, LXXXIV'),
($q$Most powerful is he who has himself in his own power.$q$, 'Seneca', 'Letters to Lucilius, XC'),
($q$Begin at once to live, and count each separate day as a separate life.$q$, 'Seneca', 'Letters to Lucilius, CI'),
($q$We learn our lessons, not for life, but for the lecture-room.$q$, 'Seneca', 'Letters to Lucilius, CVI'),
($q$Until we have begun to go without them, we fail to realise how unnecessary many things are.$q$, 'Seneca', 'Letters to Lucilius, CXXIII'),
($q$Whatever can happen at any time can happen today.$q$, 'Seneca', 'On Tranquillity of Mind, XI'),
($q$Wherever there is a human being, there is an opportunity for a kindness.$q$, 'Seneca', 'On the Happy Life, XXIV'),
-- Epictetus
($q$Men are disturbed not by things, but by the opinions about things.$q$, 'Epictetus', 'Enchiridion, 5'),
($q$Of things some are in our power, and others are not.$q$, 'Epictetus', 'Enchiridion, 1'),
($q$Seek not that the things which happen should happen as you wish; but wish the things which happen to be as they are, and you will have a tranquil flow of life.$q$, 'Epictetus', 'Enchiridion, 8'),
($q$If you would improve, be content to be thought foolish and stupid.$q$, 'Epictetus', 'Enchiridion, 13'),
($q$First say to yourself what you would be; and then do what you have to do.$q$, 'Epictetus', 'Discourses, III.23'),
($q$If you would be a good reader, read; if a writer, write.$q$, 'Epictetus', 'Discourses, II.18'),
($q$Every habit and faculty is preserved and increased by its corresponding actions.$q$, 'Epictetus', 'Discourses, II.18'),
($q$It is impossible for a man to learn what he thinks he already knows.$q$, 'Epictetus', 'Discourses, II.17'),
($q$Nothing great is produced suddenly, since not even the grape or the fig is.$q$, 'Epictetus', 'Discourses, I.15'),
($q$Practise yourself, for heaven's sake, in little things; and thence proceed to greater.$q$, 'Epictetus', 'Discourses, I.18'),
($q$Only the educated are free.$q$, 'Epictetus', 'Discourses, II.1'),
($q$No man is free who is not master of himself.$q$, 'Epictetus', 'Fragments'),
-- Ralph Waldo Emerson
($q$Trust thyself: every heart vibrates to that iron string.$q$, 'Ralph Waldo Emerson', 'Self-Reliance'),
($q$A foolish consistency is the hobgoblin of little minds.$q$, 'Ralph Waldo Emerson', 'Self-Reliance'),
($q$Nothing can bring you peace but yourself.$q$, 'Ralph Waldo Emerson', 'Self-Reliance'),
($q$Insist on yourself; never imitate.$q$, 'Ralph Waldo Emerson', 'Self-Reliance'),
($q$Nothing great was ever achieved without enthusiasm.$q$, 'Ralph Waldo Emerson', 'Circles'),
($q$Write it on your heart that every day is the best day in the year.$q$, 'Ralph Waldo Emerson', 'Society and Solitude'),
($q$The years teach much which the days never know.$q$, 'Ralph Waldo Emerson', 'Experience'),
($q$Character is higher than intellect.$q$, 'Ralph Waldo Emerson', 'The American Scholar'),
($q$Each age must write its own books.$q$, 'Ralph Waldo Emerson', 'The American Scholar'),
($q$People do not seem to realize that their opinion of the world is also a confession of character.$q$, 'Ralph Waldo Emerson', 'The Conduct of Life'),
($q$Finish each day and be done with it. You have done what you could.$q$, 'Ralph Waldo Emerson', 'Letter to his daughter'),
-- Henry David Thoreau
($q$I went to the woods because I wished to live deliberately, to front only the essential facts of life, and see if I could not learn what it had to teach.$q$, 'Henry David Thoreau', 'Walden'),
($q$Our life is frittered away by detail. Simplify, simplify.$q$, 'Henry David Thoreau', 'Walden'),
($q$The mass of men lead lives of quiet desperation.$q$, 'Henry David Thoreau', 'Walden'),
($q$If one advances confidently in the direction of his dreams, and endeavors to live the life which he has imagined, he will meet with a success unexpected in common hours.$q$, 'Henry David Thoreau', 'Walden'),
($q$If you have built castles in the air, your work need not be lost; that is where they should be. Now put the foundations under them.$q$, 'Henry David Thoreau', 'Walden'),
($q$Rather than love, than money, than fame, give me truth.$q$, 'Henry David Thoreau', 'Walden'),
($q$Things do not change; we change.$q$, 'Henry David Thoreau', 'Walden'),
($q$The cost of a thing is the amount of what I will call life which is required to be exchanged for it.$q$, 'Henry David Thoreau', 'Walden'),
($q$As if you could kill time without injuring eternity.$q$, 'Henry David Thoreau', 'Walden'),
($q$Not till we are lost do we begin to understand ourselves.$q$, 'Henry David Thoreau', 'Walden'),
($q$Every morning was a cheerful invitation to make my life of equal simplicity.$q$, 'Henry David Thoreau', 'Walden'),
($q$How vain it is to sit down to write when you have not stood up to live.$q$, 'Henry David Thoreau', 'Journal, 1851'),
($q$Write while the heat is in you.$q$, 'Henry David Thoreau', 'Journal, 1852'),
($q$It is not enough to be busy; so are the ants. The question is: What are we busy about?$q$, 'Henry David Thoreau', 'Letter to H. G. O. Blake, 1857'),
-- Benjamin Franklin
($q$If you would not be forgotten as soon as you are dead, either write things worth reading, or do things worth the writing.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1738'),
($q$Lost time is never found again.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1748'),
($q$Well done is better than well said.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1737'),
($q$Dost thou love life? Then do not squander time, for that's the stuff life is made of.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1746'),
($q$Little strokes fell great oaks.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1750'),
($q$Diligence is the mother of good luck.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1736'),
($q$Have you somewhat to do to-morrow, do it to-day.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1742'),
($q$There are no gains without pains.$q$, 'Benjamin Franklin', 'Poor Richard''s Almanack, 1745'),
($q$Resolve to perform what you ought; perform without fail what you resolve.$q$, 'Benjamin Franklin', 'Autobiography'),
($q$Lose no time; be always employed in something useful; cut off all unnecessary actions.$q$, 'Benjamin Franklin', 'Autobiography'),
($q$Let all your things have their places; let each part of your business have its time.$q$, 'Benjamin Franklin', 'Autobiography'),
($q$The morning question: What good shall I do this day?$q$, 'Benjamin Franklin', 'Autobiography'),
-- Michel de Montaigne
($q$The greatest thing in the world is to know how to belong to oneself.$q$, 'Michel de Montaigne', 'Essays, Of Solitude'),
($q$He who fears he shall suffer, already suffers what he fears.$q$, 'Michel de Montaigne', 'Essays, Of Experience'),
($q$I quote others only the better to express myself.$q$, 'Michel de Montaigne', 'Essays, Of the Education of Children'),
($q$Every man bears the whole form of the human condition.$q$, 'Michel de Montaigne', 'Essays, Of Repentance'),
-- Classical
($q$The unexamined life is not worth living.$q$, 'Socrates', 'Plato, Apology'),
($q$One swallow does not make a spring, nor does one day; and so too one day, or a short time, does not make a man blessed and happy.$q$, 'Aristotle', 'Nicomachean Ethics, I.7'),
($q$We become just by doing just acts, temperate by doing temperate acts, brave by doing brave acts.$q$, 'Aristotle', 'Nicomachean Ethics, II.1'),
($q$He who has begun has half done. Dare to be wise; begin!$q$, 'Horace', 'Epistles, I.2'),
($q$Seize the day, trusting as little as possible in tomorrow.$q$, 'Horace', 'Odes, I.11'),
($q$Dripping water hollows a stone.$q$, 'Ovid', 'Epistulae ex Ponto, IV.10'),
($q$To live is to think.$q$, 'Cicero', 'Tusculan Disputations, V'),
($q$Life is short, the art long.$q$, 'Hippocrates', 'Aphorisms, I.1'),
($q$Learning without thought is labour lost; thought without learning is perilous.$q$, 'Confucius', 'Analects, II.15'),
($q$When we see men of worth, we should think of equalling them; when we see men of a contrary character, we should turn inwards and examine ourselves.$q$, 'Confucius', 'Analects, IV.17'),
($q$The superior man is modest in his speech, but exceeds in his actions.$q$, 'Confucius', 'Analects, XIV.29'),
($q$A journey of a thousand miles begins with a single step.$q$, 'Lao Tzu', 'Tao Te Ching, 64'),
($q$He who knows others is wise; he who knows himself is enlightened.$q$, 'Lao Tzu', 'Tao Te Ching, 33'),
-- On the craft
($q$I have made this letter longer than usual, only because I have not had the time to make it shorter.$q$, 'Blaise Pascal', 'Provincial Letters, XVI'),
($q$All of humanity's problems stem from man's inability to sit quietly in a room alone.$q$, 'Blaise Pascal', 'Pensées, 139'),
($q$A man may write at any time, if he will set himself doggedly to it.$q$, 'Samuel Johnson', 'Boswell, Life of Johnson'),
($q$What is written without effort is in general read without pleasure.$q$, 'Samuel Johnson', 'Johnsonian Miscellanies'),
($q$The difference between the almost right word and the right word is really a large matter: it is the difference between the lightning-bug and the lightning.$q$, 'Mark Twain', 'Letter to George Bainton, 1888'),
($q$Eschew surplusage.$q$, 'Mark Twain', 'Fenimore Cooper''s Literary Offenses'),
($q$Knowing is not enough; we must apply. Willing is not enough; we must do.$q$, 'Johann Wolfgang von Goethe', 'Wilhelm Meister''s Journeyman Years'),
($q$Blessed is he who has found his work; let him ask no other blessedness.$q$, 'Thomas Carlyle', 'Past and Present'),
($q$The art of being wise is the art of knowing what to overlook.$q$, 'William James', 'The Principles of Psychology'),
($q$Do I contradict myself? Very well then I contradict myself, (I am large, I contain multitudes.)$q$, 'Walt Whitman', 'Song of Myself'),
($q$Let us, then, be up and doing, with a heart for any fate.$q$, 'Henry Wadsworth Longfellow', 'A Psalm of Life'),
($q$The lyf so short, the craft so long to lerne.$q$, 'Geoffrey Chaucer', 'The Parlement of Foules'),
($q$A woman must have money and a room of her own if she is to write fiction.$q$, 'Virginia Woolf', 'A Room of One''s Own');

-- A few that suit the blank page best appear in the editor; all appear on the landing page and the Desk.
UPDATE quotes SET is_favorite = true
WHERE text IN (
    $q$If you would be a good reader, read; if a writer, write.$q$,
    $q$How vain it is to sit down to write when you have not stood up to live.$q$,
    $q$Write while the heat is in you.$q$,
    $q$Begin at once to live, and count each separate day as a separate life.$q$,
    $q$The unexamined life is not worth living.$q$
);
